<script setup lang="ts">
import type { PopupPlacement } from './internal/floating';
import { computed, ref } from 'vue'; import Select from './Select.vue'; import Tree from './Tree.vue'; import type { TreeNode } from './tree-types';
import './styles/tree-select.css';
interface Node { label: string; value: string; children?: Node[]; disabled?: boolean; selectable?: boolean }
const props = withDefaults(defineProps<{ treeData: Node[]; modelValue?: string | string[]; defaultValue?: string | string[]; multiple?: boolean; treeCheckable?: boolean; showSearch?: boolean; treeDefaultExpandAll?: boolean; treeDefaultExpandedKeys?: string[]; placeholder?: string; notFoundContent?: string; disabled?: boolean; allowClear?: boolean; maxTagCount?: number; size?: 'sm' | 'md' | 'lg'; label?: string; hint?: string; error?: string; status?: 'error' | 'warning'; placement?: PopupPlacement; popupClassName?: string; popupStyle?: import('vue').CSSProperties; popupMatchSelectWidth?: boolean; open?: boolean }>(), { open: undefined, popupMatchSelectWidth: true, placeholder: '请选择…', notFoundContent: '暂无匹配选项', allowClear: true, size: 'md' });
const emit = defineEmits<{ 'update:modelValue': [value: string | string[]]; change: [value: string | string[], nodes: Node | Node[] | undefined]; 'update:open': [value: boolean] }>();
const inner = ref(props.defaultValue ?? (props.multiple || props.treeCheckable ? [] : '')); const innerOpen = ref(false), query = ref(''); const value = computed(() => props.modelValue ?? inner.value); const isMultiple = computed(() => props.multiple || props.treeCheckable); const selected = computed(() => Array.isArray(value.value) ? value.value : value.value ? [value.value] : []);
function flatten(nodes: Node[]): Node[] { return nodes.flatMap(node => [node, ...flatten(node.children ?? [])]); }
const flat = computed(() => flatten(props.treeData)); const options = computed(() => flat.value.map(node => ({ label: node.label, value: node.value, disabled: node.disabled || node.selectable === false })));
function convert(nodes: Node[]): TreeNode[] { return nodes.map(node => ({ key: node.value, title: node.label, disabled: node.disabled, selectable: node.selectable, children: node.children ? convert(node.children) : undefined })); }
const tree = computed(() => convert(props.treeData));
function update(next: string | string[]) { if (props.modelValue === undefined) inner.value = next; emit('update:modelValue', next); emit('change', next, Array.isArray(next) ? flat.value.filter(node => next.includes(node.value)) : flat.value.find(node => node.value === next)); }
function setOpen(next: boolean) { if (props.open === undefined) innerOpen.value = next; emit('update:open', next); if (!next) query.value = ''; }
function select(keys: string[], info: { selected: boolean; node: TreeNode }) { if (props.treeCheckable) return; if (isMultiple.value) update(info.selected ? [...new Set([...selected.value, info.node.key])] : selected.value.filter(value => value !== info.node.key)); else { update(keys[0] ?? ''); setOpen(false); } }
</script>
<template><Select :status="status" :placement="placement" :popup-class-name="popupClassName" :popup-style="popupStyle" :popup-match-select-width="popupMatchSelectWidth" :searchable="showSearch" @search="query = $event" :options="options" :model-value="value" :multiple="isMultiple" :disabled="disabled" :allow-clear="allowClear" :max-tag-count="maxTagCount" :size="size" :label="label" :hint="hint" :error="error" :placeholder="placeholder" :open="open ?? innerOpen" @update:open="setOpen" @update:model-value="update"><template #popup><div class="at-tree-select__popup"><Tree :tree-data="tree" :checkable="treeCheckable" :multiple="isMultiple" :selected-keys="selected" :checked-keys="selected" :filter-value="query" :default-expand-all="treeDefaultExpandAll" :default-expanded-keys="treeDefaultExpandedKeys" @select="select" @check="update($event)"><template #title="{ node }"><slot name="title" :node="flat.find(item => item.value === node.key)">{{ node.title }}</slot></template></Tree><span v-if="!flat.length" class="at-tree-select__empty">{{ notFoundContent }}</span></div></template></Select></template>
